# Fonti secondarie delle liste (servono per la colonna 'fonte' del CSV)
FONTE_2025 = 'Lista MEF 2025 (cap. media nov-2024 < 500 mln) riportata da https://www.bellelli.biz/azioni-che-non-pagano-la-tobin-tax-nel-2025/ (28/01/2025); originale MEF: https://www.mef.gov.it/pubblicita_legale/societa_2025.html'
FONTE_2026 = 'Lista MEF 2026 (cap. media nov-2025 < 500 mln) riportata da https://www.orafinanza.it/it/tobin-tax-2023-le-azioni-che-non-la-pagheranno (19/12/2025); originale MEF: https://www.mef.gov.it/pubblicita_legale/societa_2026.html'


def nomi(testo: str, sep: str):
    return [x.strip() for x in testo.replace('\n', ' ').split(sep) if x.strip()]


def lista(anno: int):
    return nomi(LISTA_2025, ',') if anno == 2025 else nomi(LISTA_2026, ';')
